  "inlineSchema": "/// @file schema.prisma\n/// @description Core database schema for User Management, Blog, and Portfolio.\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"./generated\"\n}\n\n/// User access levels for application authorization\nenum Role {\n  USER\n  ADMIN\n}\n\n/// Workflow states for manual user moderation/onboarding\nenum UserStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n/// Blog posts created by users or admins\nmodel Post {\n  id               Int       @id @default(autoincrement())\n  slug             String    @unique\n  title            String\n  description      String\n  content          String\n  imageUrl         String\n  imageHint        String\n  author           String /// Display name snapshot at time of posting\n  authorAvatarUrl  String\n  authorAvatarHint String\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n  userId           String?\n  user             User?     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  likes            Like[]\n  comments         Comment[]\n}\n\n/// Portfolio projects to showcase professional work\nmodel Project {\n  id          Int      @id @default(autoincrement())\n  title       String\n  description String\n  keyFeatures String\n  imageUrl    String\n  imageHint   String\n  gridSpan    String\n  icon        String\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  userId      String?\n  user        User?    @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n/// Social proof and feedback from clients or peers\nmodel Testimonial {\n  id         Int      @id @default(autoincrement())\n  quote      String\n  author     String\n  title      String\n  avatarUrl  String\n  avatarHint String\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n  userId     String?\n  user       User?    @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n/// Global application configuration key-value pairs\nmodel Settings {\n  id        Int      @id @default(autoincrement())\n  key       String   @unique\n  value     String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n/// NextAuth: OAuth account connections (e.g., Google, GitHub)\nmodel Account {\n  id                String   @id @default(cuid())\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String?  @db.Text\n  access_token      String?  @db.Text\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String?  @db.Text\n  session_state     String?\n  user              User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  @@unique([provider, providerAccountId])\n}\n\n/// NextAuth: Managed user sessions\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n}\n\n/// Core User entity for authentication and profile management\nmodel User {\n  id             String        @id @default(cuid())\n  name           String?\n  email          String?       @unique\n  emailVerified  DateTime?\n  image          String?\n  hashedPassword String?\n  role           Role          @default(USER)\n  status         UserStatus    @default(PENDING)\n  accounts       Account[]\n  sessions       Session[]\n  posts          Post[]\n  projects       Project[]\n  testimonials   Testimonial[]\n  comments       Comment[]\n  likes          Like[]\n  createdAt      DateTime      @default(now())\n  updatedAt      DateTime      @updatedAt\n}\n\n/// NextAuth: Secure tokens for email-based login/verification\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n\n/// User-generated feedback attached to specific blog posts\nmodel Comment {\n  id        Int      @id @default(autoincrement())\n  content   String\n  postId    Int\n  post      Post     @relation(fields: [postId], references: [id], onDelete: Cascade)\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n/// Simple engagement tracking for blog posts\nmodel Like {\n  id        Int      @id @default(autoincrement())\n  postId    Int\n  post      Post     @relation(fields: [postId], references: [id], onDelete: Cascade)\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, postId])\n}\n",
